			fmt.Fprintf(cmd.OutOrStdout(), "recorded %s hint for session %s (generation %d)\n", hint.LastEvent, hint.SessionID, hint.Generation)
			if warning != "" {
				fmt.Fprintln(cmd.ErrOrStderr(), warning)
