+	pending := cursor.PendingDistill && w.distill || cursor.PendingSeed && w.seedAgent != "none"
+	if !pending {
+		return false
+	}
+	return w.distillEvery <= 0 || now.Sub(cursor.LastRefreshAt) <= w.distillEvery
+}
